"""Database layer for SimpleChat.

This is the *only* module in the project allowed to talk to SQLite (the course's
"כלל ברזל" — the frontend never reaches the DB directly; Meeting 5B). Every query
uses parameterized statements (``?`` placeholders) so user input can never be
interpreted as SQL — this protects the search endpoint from SQL injection
(Meeting 5A).

Connections are handed out through a context manager so they are always closed,
and rows come back as ``sqlite3.Row`` objects so callers can read columns by
name.
"""

import os
import sqlite3
from contextlib import contextmanager
from typing import Iterator, Optional

from dotenv import load_dotenv

load_dotenv()

# Resolve the DB path so it works no matter which directory uvicorn is launched
# from. A relative DATABASE_URL (e.g. "backend/chat_db.sqlite") is anchored to
# the project root (the parent of this backend/ folder).
_BACKEND_DIR = os.path.dirname(os.path.abspath(__file__))
_PROJECT_ROOT = os.path.dirname(_BACKEND_DIR)
_env_db = os.getenv("DATABASE_URL")
if _env_db:
    DATABASE_PATH = _env_db if os.path.isabs(_env_db) else os.path.join(_PROJECT_ROOT, _env_db)
else:
    DATABASE_PATH = os.path.join(_BACKEND_DIR, "chat_db.sqlite")


@contextmanager
def get_connection() -> Iterator[sqlite3.Connection]:
    """Yield a SQLite connection that commits on success and always closes.

    Usage::

        with get_connection() as conn:
            conn.execute(...)
    """
    conn = sqlite3.connect(DATABASE_PATH)
    conn.row_factory = sqlite3.Row
    # Enforce the FOREIGN KEY constraints declared in the schema.
    conn.execute("PRAGMA foreign_keys = ON")
    try:
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def init_db() -> None:
    """Create every table if it does not already exist.

    Safe to call on every startup — ``CREATE TABLE IF NOT EXISTS`` is idempotent.
    """
    with get_connection() as conn:
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE NOT NULL,
                hashed_password TEXT NOT NULL,
                created_at TEXT DEFAULT (datetime('now'))
            );

            CREATE TABLE IF NOT EXISTS messages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                sender_username TEXT NOT NULL,
                content TEXT NOT NULL,
                timestamp TEXT DEFAULT (datetime('now')),
                group_id INTEGER,
                recipient_username TEXT,        -- set only for 1-to-1 direct messages
                file_name TEXT,
                file_path TEXT,
                file_type TEXT,
                FOREIGN KEY (sender_username) REFERENCES users(username),
                FOREIGN KEY (recipient_username) REFERENCES users(username),
                FOREIGN KEY (group_id) REFERENCES group_chats(id)
            );

            CREATE TABLE IF NOT EXISTS group_chats (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT UNIQUE NOT NULL,
                created_at TEXT DEFAULT (datetime('now'))
            );

            CREATE TABLE IF NOT EXISTS group_members (
                group_id INTEGER,
                username TEXT,
                PRIMARY KEY (group_id, username),
                FOREIGN KEY (group_id) REFERENCES group_chats(id),
                FOREIGN KEY (username) REFERENCES users(username)
            );

            -- [FEATURE] Read receipts for direct messages: stores, per (reader,
            -- peer) pair, the highest message id the reader has seen in that
            -- 1-to-1 conversation. Additive — only DMs consult this table.
            CREATE TABLE IF NOT EXISTS dm_reads (
                username TEXT NOT NULL,        -- the viewer who has read up to ...
                peer TEXT NOT NULL,            -- ... this other participant
                last_read_id INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (username, peer)
            );
            """
        )
        # Migration for databases created before direct messages existed: add the
        # recipient_username column if it is missing.
        cols = {r["name"] for r in conn.execute("PRAGMA table_info(messages)")}
        if "recipient_username" not in cols:
            conn.execute("ALTER TABLE messages ADD COLUMN recipient_username TEXT")
        # [FEATURE] Edit/delete support: an "edited" flag and a soft-delete flag so
        # an edited message can show an "(edited)" marker and a deleted one can be
        # rendered as "message deleted" without breaking id ordering.
        if "edited" not in cols:
            conn.execute("ALTER TABLE messages ADD COLUMN edited INTEGER DEFAULT 0")
        if "is_deleted" not in cols:
            conn.execute("ALTER TABLE messages ADD COLUMN is_deleted INTEGER DEFAULT 0")


# --------------------------------------------------------------------------- #
# Users
# --------------------------------------------------------------------------- #
def create_user(username: str, hashed_password: str) -> None:
    """Insert a new user. Raises ``sqlite3.IntegrityError`` if the name is taken."""
    with get_connection() as conn:
        conn.execute(
            "INSERT INTO users (username, hashed_password) VALUES (?, ?)",
            (username, hashed_password),
        )


def get_user_by_username(username: str) -> Optional[sqlite3.Row]:
    """Return the user row for ``username`` or ``None`` if not found."""
    with get_connection() as conn:
        cur = conn.execute(
            "SELECT id, username, hashed_password, created_at "
            "FROM users WHERE username = ?",
            (username,),
        )
        return cur.fetchone()


# --------------------------------------------------------------------------- #
# Messages
# --------------------------------------------------------------------------- #
# A message can live in exactly one "channel": the public feed
# (group_id IS NULL AND recipient_username IS NULL), a group (group_id set), or a
# 1-to-1 direct conversation (recipient_username set). The SELECT column list is
# shared so every read returns the same shape.
_MSG_COLS = (
    "id, sender_username, content, timestamp, group_id, "
    "recipient_username, file_name, file_type, "
    "COALESCE(edited, 0) AS edited, COALESCE(is_deleted, 0) AS is_deleted"  # [FEATURE]
)


def insert_message(
    sender_username: str,
    content: str,
    group_id: Optional[int] = None,
    recipient_username: Optional[str] = None,
    file_name: Optional[str] = None,
    file_path: Optional[str] = None,
    file_type: Optional[str] = None,
) -> sqlite3.Row:
    """Insert a message and return the freshly created row."""
    with get_connection() as conn:
        cur = conn.execute(
            """
            INSERT INTO messages
                (sender_username, content, group_id, recipient_username,
                 file_name, file_path, file_type)
            VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                sender_username, content, group_id, recipient_username,
                file_name, file_path, file_type,
            ),
        )
        new_id = cur.lastrowid
        row = conn.execute(
            f"SELECT {_MSG_COLS} FROM messages WHERE id = ?", (new_id,)
        ).fetchone()
        return row


def get_messages(group_id: Optional[int] = None) -> list[sqlite3.Row]:
    """Return messages ordered oldest→newest (newest at the bottom of the UI).

    ``group_id=None`` returns the public global chat; an integer returns the
    messages for that group only. Direct messages are *never* included here —
    the public branch explicitly excludes them so private DMs cannot leak into
    the global feed.
    """
    with get_connection() as conn:
        if group_id is None:
            cur = conn.execute(
                f"SELECT {_MSG_COLS} FROM messages "
                "WHERE group_id IS NULL AND recipient_username IS NULL "
                "ORDER BY id ASC"
            )
        else:
            cur = conn.execute(
                f"SELECT {_MSG_COLS} FROM messages "
                "WHERE group_id = ? ORDER BY id ASC",
                (group_id,),
            )
        return cur.fetchall()


def get_direct_messages(user_a: str, user_b: str) -> list[sqlite3.Row]:
    """Return the 1-to-1 conversation between two users, oldest→newest.

    Authorization is enforced *by construction*: only messages where the two
    parties are exactly ``user_a`` and ``user_b`` (in either direction) are
    returned, so a caller can only ever read their own conversations.
    """
    with get_connection() as conn:
        cur = conn.execute(
            f"SELECT {_MSG_COLS} FROM messages "
            "WHERE recipient_username IS NOT NULL AND ("
            "  (sender_username = ? AND recipient_username = ?) OR "
            "  (sender_username = ? AND recipient_username = ?)) "
            "ORDER BY id ASC",
            (user_a, user_b, user_b, user_a),
        )
        return cur.fetchall()


def search_messages(query: str, group_id: Optional[int] = None) -> list[sqlite3.Row]:
    """Free-text search over message content using a parameterized LIKE query.

    The ``%`` wildcards are bound as data, never formatted into the SQL string,
    so this is safe against SQL injection.
    """
    like = f"%{query}%"
    with get_connection() as conn:
        if group_id is None:
            # Public search also excludes direct messages (recipient IS NULL) so
            # private DMs never surface in a public search.
            cur = conn.execute(
                f"SELECT {_MSG_COLS} FROM messages "
                "WHERE group_id IS NULL AND recipient_username IS NULL "
                "AND content LIKE ? ORDER BY id ASC",
                (like,),
            )
        else:
            cur = conn.execute(
                f"SELECT {_MSG_COLS} FROM messages "
                "WHERE group_id = ? AND content LIKE ? ORDER BY id ASC",
                (group_id, like),
            )
        return cur.fetchall()


def search_all_for_user(query: str, username: str) -> list[sqlite3.Row]:
    """[FEATURE] GLOBAL SEARCH: partial substring search across every message the
    caller may see — the public chat, groups they belong to, and their own direct
    messages. Each row keeps its channel fields (group_id / recipient_username /
    sender_username) so the UI can label the result and jump to it.

    Uses a parameterized ``LIKE '%query%'`` (substring; case-insensitive for ASCII,
    and Hebrew has no case so it matches naturally). Authorization is built into
    the WHERE clause: only public, the caller's groups, and the caller's DMs.
    """
    like = f"%{query}%"
    with get_connection() as conn:
        return conn.execute(
            f"SELECT {_MSG_COLS} FROM messages "
            "WHERE content LIKE ? AND ("
            "  (group_id IS NULL AND recipient_username IS NULL) OR "
            "  group_id IN (SELECT group_id FROM group_members WHERE username = ?) OR "
            "  (recipient_username IS NOT NULL AND "
            "   (sender_username = ? OR recipient_username = ?))"
            ") ORDER BY id ASC",
            (like, username, username, username),
        ).fetchall()


def get_message_file(message_id: int) -> Optional[sqlite3.Row]:
    """Return the stored file metadata for a message, or ``None``.

    [SECURITY HARDENING] M-2: also returns ``group_id``, ``recipient_username``
    and ``sender_username`` so the caller can run an authorization check (group
    membership or DM participation) before serving the file.
    """
    with get_connection() as conn:
        return conn.execute(
            "SELECT file_name, file_path, file_type, group_id, "
            "recipient_username, sender_username FROM messages WHERE id = ?",
            (message_id,),
        ).fetchone()


def get_all_usernames(exclude: Optional[str] = None) -> list[str]:
    """Return every registered username (optionally excluding one), sorted.

    Used by the frontend to let a user pick someone to start a direct message
    with.
    """
    with get_connection() as conn:
        rows = conn.execute(
            "SELECT username FROM users ORDER BY username COLLATE NOCASE"
        ).fetchall()
    return [r["username"] for r in rows if r["username"] != exclude]


def user_exists(username: str) -> bool:
    """Return ``True`` if a user with this username is registered."""
    with get_connection() as conn:
        return (
            conn.execute(
                "SELECT 1 FROM users WHERE username = ?", (username,)
            ).fetchone()
            is not None
        )


def get_latest_incoming(username: str) -> Optional[sqlite3.Row]:
    """Return the most recent message *addressed to* ``username`` by someone else.

    Powers the cross-conversation "new message" notification (the badge/toast
    shown even when that conversation's window is closed). "Addressed to me"
    means a direct message to me, or a message in a group I belong to — never my
    own messages.
    """
    with get_connection() as conn:
        return conn.execute(
            "SELECT id, sender_username, recipient_username, group_id "
            "FROM messages "
            "WHERE sender_username != ? AND ("
            "  recipient_username = ? OR "
            "  group_id IN (SELECT group_id FROM group_members WHERE username = ?)"
            ") ORDER BY id DESC LIMIT 1",
            (username, username, username),
        ).fetchone()


# --------------------------------------------------------------------------- #
# [FEATURE] Edit / delete own messages
# --------------------------------------------------------------------------- #
def get_message_owner(message_id: int) -> Optional[sqlite3.Row]:
    """Return id/sender/channel info for a message (for ownership checks)."""
    with get_connection() as conn:
        return conn.execute(
            "SELECT id, sender_username, group_id, recipient_username "
            "FROM messages WHERE id = ?",
            (message_id,),
        ).fetchone()


def update_message(message_id: int, content: str) -> Optional[sqlite3.Row]:
    """Edit a message's text and flag it as edited. Returns the updated row."""
    with get_connection() as conn:
        conn.execute(
            "UPDATE messages SET content = ?, edited = 1 WHERE id = ?",
            (content, message_id),
        )
        return conn.execute(
            f"SELECT {_MSG_COLS} FROM messages WHERE id = ?", (message_id,)
        ).fetchone()


def soft_delete_message(message_id: int) -> Optional[sqlite3.Row]:
    """Soft-delete a message (keep the row, blank the content). Returns the row."""
    with get_connection() as conn:
        conn.execute(
            "UPDATE messages SET is_deleted = 1, content = '', "
            "file_name = NULL, file_path = NULL, file_type = NULL WHERE id = ?",
            (message_id,),
        )
        return conn.execute(
            f"SELECT {_MSG_COLS} FROM messages WHERE id = ?", (message_id,)
        ).fetchone()


# --------------------------------------------------------------------------- #
# [FEATURE] Read receipts (direct messages only)
# --------------------------------------------------------------------------- #
def mark_dm_read(username: str, peer: str) -> int:
    """Mark the DM conversation with ``peer`` as read up to its newest message.

    Records the highest message id in the (username, peer) conversation as the
    reader's ``last_read_id``. Returns that id (0 if there are no messages yet).
    """
    with get_connection() as conn:
        row = conn.execute(
            "SELECT MAX(id) AS max_id FROM messages "
            "WHERE recipient_username IS NOT NULL AND ("
            "  (sender_username = ? AND recipient_username = ?) OR "
            "  (sender_username = ? AND recipient_username = ?))",
            (username, peer, peer, username),
        ).fetchone()
        last_id = row["max_id"] or 0
        conn.execute(
            "INSERT INTO dm_reads (username, peer, last_read_id) VALUES (?, ?, ?) "
            "ON CONFLICT(username, peer) DO UPDATE SET "
            "last_read_id = MAX(last_read_id, excluded.last_read_id)",
            (username, peer, last_id),
        )
        return last_id


def get_dm_last_read(username: str, peer: str) -> int:
    """Return how far ``username`` has read in the conversation with ``peer``."""
    with get_connection() as conn:
        row = conn.execute(
            "SELECT last_read_id FROM dm_reads WHERE username = ? AND peer = ?",
            (username, peer),
        ).fetchone()
        return row["last_read_id"] if row else 0


# --------------------------------------------------------------------------- #
# Group chats
# --------------------------------------------------------------------------- #
def create_group(
    name: str, creator: str, members: Optional[list[str]] = None
) -> sqlite3.Row:
    """Create a group and seed its membership.

    [FEATURE] PRIVATE GROUPS: the creator is always a member; ``members`` are the
    additionally-invited usernames. Callers must pass only **existing** users (the
    route filters them) — group_members.username is a FOREIGN KEY, so an unknown
    name would abort the whole creation. ``INSERT OR IGNORE`` keeps duplicates
    (e.g. the creator appearing in ``members``) harmless.
    """
    everyone = [creator] + [m for m in (members or []) if m != creator]
    with get_connection() as conn:
        cur = conn.execute("INSERT INTO group_chats (name) VALUES (?)", (name,))
        group_id = cur.lastrowid
        conn.executemany(
            "INSERT OR IGNORE INTO group_members (group_id, username) VALUES (?, ?)",
            [(group_id, u) for u in everyone],
        )
        return conn.execute(
            "SELECT id, name, created_at FROM group_chats WHERE id = ?",
            (group_id,),
        ).fetchone()


def get_groups_for_user(username: str) -> list[sqlite3.Row]:
    """[FEATURE] PRIVATE GROUPS: return only the groups ``username`` belongs to.

    This is what makes a group invite-only/visible-to-members-only: a user never
    even sees a group they were not added to. Reading/posting is independently
    gated by :func:`is_group_member` (Authorization, Meeting 4A).
    """
    with get_connection() as conn:
        return conn.execute(
            "SELECT g.id, g.name, g.created_at FROM group_chats g "
            "JOIN group_members m ON m.group_id = g.id "
            "WHERE m.username = ? ORDER BY g.id DESC",
            (username,),
        ).fetchall()


def join_group(group_id: int, username: str) -> bool:
    """Add ``username`` to a group. Returns ``False`` if the group does not exist."""
    with get_connection() as conn:
        exists = conn.execute(
            "SELECT 1 FROM group_chats WHERE id = ?", (group_id,)
        ).fetchone()
        if not exists:
            return False
        conn.execute(
            "INSERT OR IGNORE INTO group_members (group_id, username) VALUES (?, ?)",
            (group_id, username),
        )
        return True


# --------------------------------------------------------------------------- #
# [SECURITY HARDENING] H-2 / M-2 — Authorization helpers
# These back the membership checks that decide "what may you do?" (the course's
# Authorization concept, Meeting 4A slide 10). A user may read/post in a group
# only if they appear in ``group_members``.
# --------------------------------------------------------------------------- #
def is_group_member(group_id: int, username: str) -> bool:
    """Return ``True`` if ``username`` is a member of ``group_id``."""
    with get_connection() as conn:
        return (
            conn.execute(
                "SELECT 1 FROM group_members WHERE group_id = ? AND username = ?",
                (group_id, username),
            ).fetchone()
            is not None
        )


def get_group_member_usernames(group_id: int) -> set[str]:
    """Return the set of usernames that are members of ``group_id``."""
    with get_connection() as conn:
        rows = conn.execute(
            "SELECT username FROM group_members WHERE group_id = ?",
            (group_id,),
        ).fetchall()
        return {r["username"] for r in rows}
